import 'dart:async';
import 'dart:convert';
import 'package:flutter_test/flutter_test.dart';
import 'package:material_ui/material_ui.dart';
import 'package:http/http.dart' as http;
import 'package:http/testing.dart';
import 'package:zhixiugong_engineer/api.dart';
import 'package:zhixiugong_engineer/common.dart';
import 'package:zhixiugong_engineer/inventory.dart';
import 'package:zhixiugong_engineer/device_pages.dart';
import 'package:zhixiugong_engineer/assistant_pages.dart';
const device='11111111-1111-4111-8111-111111111111';
void main(){
 test('QR accepts own device IDs and rejects external or executable links',(){expect(deviceCode(device,trustedHost:'43.139.91.94'),device);expect(deviceCode('https://43.139.91.94:8441/device-scan.html?assetId=$device',trustedHost:'43.139.91.94'),device);expect(deviceCode('https://evil.test/?deviceId=$device',trustedHost:'43.139.91.94'),isNull);expect(deviceCode('javascript:alert(1)',trustedHost:'43.139.91.94'),isNull);expect(deviceCode('https://user:pass@43.139.91.94/?id=$device',trustedHost:'43.139.91.94'),isNull);});
 test('scope preserves order filters and uses explicit enterprise selection',(){final u=Uri.parse(scoped('/engineer/orders?status=REPAIRING','service-one'));expect(u.queryParameters,{'status':'REPAIRING','serviceId':'service-one'});});
 test('warehouse actions obey actual direction and state',(){expect(materialAction({'kind':'ISSUE','status':'SHIPPED'}),'receive');expect(materialAction({'kind':'RETURN','status':'APPROVED'}),'ship');expect(materialAction({'kind':'ISSUE','status':'RECEIVED'}),isNull);expect(materialAction({'kind':'RETURN','status':'PENDING'}),isNull);});
 test('report template never claims unverified work is complete',(){final draft=repairDraft(const ServiceOrder({'orderNo':'work','faultDescription':'reported fault'}),'','','');expect(draft,contains('未经现场验证'));expect(draft,contains('待验证，不代表维修完成'));expect(draft,contains('未自动登记用料'));});
 test('SSE safely decodes split UTF8 and retains conversation metadata',()async{final payload=utf8.encode('data: {"event":"message","answer":"检查温度","conversation_id":"thread"}\n\ndata: {"event":"message_end","conversation_id":"thread"}\n\n');final abort=Completer<void>();final transport=MockClient.streaming((r,body)async{expect(r.headers['Authorization'],'Bearer test');expect(r.url.queryParameters['serviceId'],'company-one');expect(r,isA<http.Abortable>());final sent=jsonDecode(utf8.decode(await body.expand((x)=>x).toList()));expect(sent['query'],'test query');return http.StreamedResponse(Stream.fromIterable([payload.sublist(0,61),payload.sublist(61,63),payload.sublist(63)]),200,headers:{'content-type':'text/event-stream'});});final api=Api(streamClientFactory:()=>transport)..token='test';final events=await api.chat('test query',serviceId:'company-one',abort:abort.future).toList();expect(events.first['answer'],'检查温度');expect(events.last['conversation_id'],'thread');api.dispose();});
 test('unconfigured AI produces a clear failure, not a fabricated reply',()async{final api=Api(streamClientFactory:()=>MockClient((_)async=>http.Response('{"message":"DIFY_API_KEY missing"}',503)));await expectLater(api.chat('test',serviceId:'company').toList(),throwsA(isA<ApiFailure>().having((e)=>e.message,'message',contains('暂未配置'))));api.dispose();});
 testWidgets('failed material request retains form and is scoped to its selected company',(tester)async{var writes=0;final api=Api(client:MockClient((r)async{writes++;expect(r.url.queryParameters['serviceId'],'company-one');final data=jsonDecode(r.body);expect(data['kind'],'ISSUE');expect(data['quantity'],2);expect(data['partId'],'part-one');return http.Response('{"message":"stock changed"}',409);}));await tester.pumpWidget(MaterialApp(home:MaterialForm(api:api,serviceId:'company-one',kind:'ISSUE',data:{'warehouses':[{'id':'warehouse-one','name':'Warehouse A','kind':'CENTRAL','isActive':true}],'parts':[{'id':'part-one','name':'Part A','isActive':true}]})));await tester.tap(find.byType(DropdownButtonFormField<String>).at(0));await tester.pumpAndSettle();await tester.tap(find.text('Warehouse A').last);await tester.pumpAndSettle();await tester.tap(find.byType(DropdownButtonFormField<String>).at(1));await tester.pumpAndSettle();await tester.tap(find.text('Part A').last);await tester.pumpAndSettle();await tester.enterText(find.byType(TextFormField).at(0),'2');await tester.ensureVisible(find.text('确认提交'));await tester.tap(find.text('确认提交'));await tester.pumpAndSettle();expect(writes,1);expect(find.textContaining('内容已保留'),findsOneWidget);expect(find.text('2'),findsOneWidget);expect(tester.takeException(),isNull);api.dispose();});
}
